// Calcula metricas del embudo y alertas a partir del CRM
const hoy = $now.toFormat('yyyy-LL-dd');
const leads = $('Leer Leads').all().map(i => i.json).filter(l => l && l.ID_Lead);
const act = $('Leer Actividad').all().map(i => i.json).filter(a => a && a.Timestamp);
const norm = s => String(s||'').trim();
const dstr = s => String(s||'').slice(0,10);
const byEstado = {};
let sumScore = 0, nScore = 0;
const sinSiguientePaso = [];
const seguimientosVencidos = [];
const proximos = [];
for (const l of leads) {
  const e = norm(l.Estado) || 'sin_estado';
  byEstado[e] = (byEstado[e]||0) + 1;
  const sc = Number(l.Score_ICP);
  if (!isNaN(sc) && sc > 0) { sumScore += sc; nScore++; }
  const activo = ['borrador_creado','respondio','en_pipeline','agendado','nutrir'].includes(e);
  const fsp = dstr(l.Fecha_Siguiente_Paso);
  if (activo && !fsp) sinSiguientePaso.push(l.Empresa + ' (' + l.Contacto + ')');
  if (activo && fsp && fsp < hoy) seguimientosVencidos.push(l.Empresa + ' — venció ' + fsp);
  if (activo && fsp && fsp >= hoy) proximos.push({ empresa: l.Empresa, fecha: fsp });
}
const actHoy = act.filter(a => dstr(a.Timestamp) === hoy);
const accionesHoy = {};
for (const a of actHoy) { const k = norm(a.Accion)||'otro'; accionesHoy[k] = (accionesHoy[k]||0)+1; }
proximos.sort((a,b)=> a.fecha.localeCompare(b.fecha));
const metrics = {
  fecha: hoy,
  total_leads: leads.length,
  embudo_por_estado: byEstado,
  score_promedio: nScore ? Math.round(sumScore/nScore) : 0,
  actividad_hoy: accionesHoy,
  reuniones_agendadas_total: byEstado['agendado'] || 0,
  en_pipeline_total: byEstado['en_pipeline'] || 0,
  alertas: {
    sin_siguiente_paso: sinSiguientePaso.slice(0,15),
    seguimientos_vencidos: seguimientosVencidos.slice(0,15)
  },
  proximos_seguimientos: proximos.slice(0,15)
};
const system = [
'<identidad>Eres analista comercial senior de ACCES GROUP. Generas un reporte ejecutivo diario claro y accionable.</identidad>',
'<reglas>Usa SOLO los datos provistos, sin inventar. Espanol ejecutivo. Devuelve HTML simple (h2,h3,ul,table). Incluye: (1) Resumen del dia, (2) Embudo por etapa, (3) Alertas (sin siguiente paso, seguimientos vencidos), (4) Proximos seguimientos, (5) 3 recomendaciones de Siguiente Mejor Accion priorizadas por impacto. No incluyas firma.</reglas>',
'<salida>Devuelve SOLO el HTML del reporte, sin ``` y sin texto fuera del HTML.</salida>'
].join('\n');
const user = 'Fecha: ' + hoy + '\nDatos del CRM (JSON):\n' + JSON.stringify(metrics, null, 2) + '\n\nGenera el reporte ejecutivo en HTML.';
return [{ json: { hoy, metrics, system, user } }];

